def rolling_max(numbers: List[int]) -> List[int]:
    if not numbers:
        return []

    result = []
    window = []

    for i in range(len(numbers)):
        if window and window[0] <= i - len(window):
            window.pop(0)

        while window and numbers[window[-1]] <= numbers[i]:
            window.pop()

        window.append(i)

        if i >= len(window) - 1:
            result.append(numbers[window[0]])

    return result
