    if a + b > c and a + c > b and b + c > a:
        # Step 2: Calculate area
        s = (a + b + c) / 2
        area = math.sqrt(s * (s - a) * (s - b) * (s - c))

        # Step 3: Round to 2 decimal points
        area = round(area, 2)

        # Step 4: Return result
        return area
    else:
        return -1

